    pub const VT_HAS_OFFSET_S: ::flatbuffers::VOffsetT = 16;
    pub const VT_HAS_BRACKET_LO_S: ::flatbuffers::VOffsetT = 18;
    pub const VT_HAS_BRACKET_HI_S: ::flatbuffers::VOffsetT = 20;

