impl CLGBoundaryT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<CLGBoundary<'b>> {
        let PAIR_INDEX_tmp = self.PAIR_INDEX.as_ref().map(|x| x.pack());
        let PAIR_INDEX = PAIR_INDEX_tmp.as_ref();
        let OFFSET_S = self.OFFSET_S;
        let BRACKET_LO_S = self.BRACKET_LO_S;
        let BRACKET_HI_S = self.BRACKET_HI_S;
        let CAUSES = Some({
            let x = &self.CAUSES;
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack()).collect();_fbb.create_vector(&w)
        });
        let RAY_TIMES = Some({
            let x = &self.RAY_TIMES;
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack()).collect();_fbb.create_vector(&w)
        });
        let HAS_OFFSET_S = self.HAS_OFFSET_S;
        let HAS_BRACKET_LO_S = self.HAS_BRACKET_LO_S;
        let HAS_BRACKET_HI_S = self.HAS_BRACKET_HI_S;
        CLGBoundary::create(_fbb, &CLGBoundaryArgs{
            PAIR_INDEX,
            OFFSET_S,
            BRACKET_LO_S,
            BRACKET_HI_S,
            CAUSES,
            RAY_TIMES,
            HAS_OFFSET_S,
            HAS_BRACKET_LO_S,
            HAS_BRACKET_HI_S,
        })
    }
}

