#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct CLGT {
    pub GRAPH_ID: alloc::string::String,
    pub PAYLOAD: clgPayloadClass,
    pub DEFINITION: Option<alloc::boxed::Box<CLGDefinitionT>>,
    pub STATE_BLOCK: Option<alloc::boxed::Box<CLGStateBlockT>>,
    pub RESULT: Option<alloc::boxed::Box<CLGResultT>>,
    pub HAS_PAYLOAD: bool,
}

impl Default for CLGT {
    fn default() -> Self {
        Self {
            GRAPH_ID: alloc::string::ToString::to_string(""),
            PAYLOAD: clgPayloadClass::UNSPECIFIED,
            DEFINITION: None,
            STATE_BLOCK: None,
            RESULT: None,
            HAS_PAYLOAD: false,
        }
    }
}

impl CLGT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<CLG<'b>> {
        let GRAPH_ID = Some({
            let x = &self.GRAPH_ID;
            _fbb.create_string(x)
        });
        let PAYLOAD = self.PAYLOAD;
        let DEFINITION = self.DEFINITION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATE_BLOCK = self.STATE_BLOCK.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let RESULT = self.RESULT.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let HAS_PAYLOAD = self.HAS_PAYLOAD;
        CLG::create(_fbb, &CLGArgs{
            GRAPH_ID,
            PAYLOAD,
            DEFINITION,
            STATE_BLOCK,
            RESULT,
            HAS_PAYLOAD,
        })
    }
}

/// Verifies that a buffer of bytes contains a `CLG`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_clg_unchecked`.
#[inline]
pub fn root_as_clg(buf: &[u8]) -> Result<CLG<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<CLG>(buf)
}

